    # Add clientside callback for copying
    app.clientside_callback(
        """
        function(n_clicks) {
            if (!n_clicks) {
                // Return special value to prevent update
                return window.dash_clientside.no_update;
            }
            // Find all selectable text spans in embedding status
            const spans = document.querySelectorAll('#embedding-status-indicator .selectable-text');
            if (spans.length > 0) {
                const text = Array.from(spans).map(s => s.textContent).join(' ');
                navigator.clipboard.writeText(text).then(function() {
                    console.log("Copied embedding status to clipboard");
                }).catch(function(err) {
                    console.error("Failed to copy:", err);
                });
            }
            // Return special value to prevent update
            return window.dash_clientside.no_update;
        }
        """,
        Output("embedding-status-indicator", "children", allow_duplicate=True),
        Input("btn-copy-embedding-status", "n_clicks"),
        prevent_initial_call=True,
    )


def _check_vector_search_status():
    """Check if sqlite-vss is available for vector search.

    Returns:
        tuple: (is_available, status_message, color)
    """
    try:
        import sqlite3
        import sqlite_vss

        # Try to load the extension
        conn = sqlite3.connect(":memory:")
        try:
            sqlite_vss.load(conn)
            conn.close()
            return True, "✓ Vector search (sqlite-vss) is available - embeddings will be indexed for fast similarity search", "success"
        except Exception as e:
            conn.close()
            error_msg = str(e).lower()
            if "not authorized" in error_msg or "load_extension" in error_msg:
                # Try with load_extension enabled
                try:
                    conn = sqlite3.connect(":memory:")
                    conn.enable_load_extension(True)
                    sqlite_vss.load(conn)
                    conn.close()
                    return True, "✓ Vector search (sqlite-vss) is available - embeddings will be indexed for fast similarity search", "success"
                except Exception as e2:
                    return False, f"sqlite-vss loaded but cannot enable extension: {e2}", "warning"
            return False, f"sqlite-vss cannot load extension: {e}", "warning"
    except ImportError:
        return False, "sqlite-vss Python package is not installed. Install with: pip install sqlite-vss", "danger"
    except Exception as e:
        return False, f"Vector search error: {e}", "danger"


